const dialog=document.querySelector('dialog'),track=document.querySelector('#track'),saved=document.querySelector('#saved');
document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{track.value=b.dataset.track;saved.textContent='';dialog.showModal()});document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('form').onsubmit=e=>{e.preventDefault();localStorage.setItem('astra-focus',track.value);saved.textContent=`Your starting point: ${track.value}. Saved on this device.`};
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let motion=!reduced;const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&motion){anime.animate(e.target,{opacity:[0,1],y:[30,0],duration:1000,ease:'outCubic'});observer.unobserve(e.target)}}),{threshold:.2});document.querySelectorAll('.copy,.versus-copy').forEach(e=>observer.observe(e));
function scrollMotion(){if(!motion)return;document.querySelectorAll('.scene').forEach(scene=>{const rect=scene.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight){const p=(innerHeight/2-rect.top-rect.height/2)/innerHeight;scene.querySelector('.art').style.transform=`translateY(${p*18}px)`}})}window.addEventListener('scroll',scrollMotion,{passive:true});document.querySelector('#motion').onclick=e=>{motion=!motion;document.body.classList.toggle('still',!motion);e.target.textContent='Motion '+(motion?'on':'off');if(!motion)document.querySelectorAll('.art').forEach(e=>e.style.transform='none')};if(reduced)document.querySelector('#motion').textContent='Motion off';
